mapper.select:
select r.reservation_id, r.user_id, u.user_name, u.nick_name, p.student_no,
  cp.campus_id, cp.campus_name, bd.building_id, bd.building_name,
  fl.floor_id, fl.floor_name, r.room_id, rm.room_name, r.seat_id, s.seat_no,
  r.start_time, r.end_time, r.check_deadline, r.status, r.cancel_time, r.create_time
from seatflow_reservation r
  inner join sys_user u on u.user_id = r.user_id
  left join seatflow_user_profile p on p.user_id = r.user_id
  inner join seatflow_seat s on s.seat_id = r.seat_id
  inner join seatflow_room rm on rm.room_id = r.room_id
  inner join seatflow_floor fl on fl.floor_id = rm.floor_id
  inner join seatflow_building bd on bd.building_id = fl.building_id
  inner join seatflow_campus cp on cp.campus_id = bd.campus_id


        and u.user_name like concat('%', #{userName}, '%')


        and p.student_no like concat('%', #{studentNo}, '%')

    and cp.campus_id = #{campusId}
    and bd.building_id = #{buildingId}
    and fl.floor_id = #{floorId}
    and r.room_id = #{roomId}
    and r.status = #{status}
    and r.start_time >= #{beginTime}
    and r.end_time <= #{endTime}

order by r.start_time desc, r.reservation_id desc

select r.status, count(*) as count
from seatflow_reservation r
  inner join sys_user u on u.user_id = r.user_id
  left join seatflow_user_profile p on p.user_id = r.user_id
  inner join seatflow_seat s on s.seat_id = r.seat_id
  inner join seatflow_room rm on rm.room_id = r.room_id
  inner join seatflow_floor fl on fl.floor_id = rm.floor_id
  inner join seatflow_building bd on bd.building_id = fl.building_id
  inner join seatflow_campus cp on cp.campus_id = bd.campus_id


        and u.user_name like concat('%', #{userName}, '%')


        and p.student_no like concat('%', #{studentNo}, '%')

    and cp.campus_id = #{campusId}
    and bd.building_id = #{buildingId}
    and fl.floor_id = #{floorId}
    and r.room_id = #{roomId}
    and r.start_time >= #{beginTime}
    and r.end_time <= #{endTime}

group by r.status

mapper.update:
update seatflow_reservation set status = 'cancelled', cancel_time = #{cancelTime},
  update_by = #{updateBy}, update_time = #{cancelTime}
where reservation_id = #{reservationId} and user_id = #{userId}
  and status = 'pending_checkin' and start_time > #{cancelTime}
